import { Effect } from "effect";

import type { TerminalSession } from "./types";

const DEFAULT_COLS = 120;
const DEFAULT_ROWS = 30;

export interface AttachOptions {
  readonly threadId: string;
  readonly terminalId: string;
  readonly cwd: string;
  readonly resume?: boolean;
}

/** Finds the session for a terminal, starting one when none is running. */
export const attach = Effect.fn("Terminals.attach")(function* (options: AttachOptions) {
  const sessions = yield* TerminalSessions;
  const session = sessions.get(options.threadId, options.terminalId);
  return session ?? (yield* sessions.start({ ...options, cols: DEFAULT_COLS, rows: DEFAULT_ROWS }));
});

export function label(session: TerminalSession, index: number): string {
  const title = session.title.trim();
  return title.length > 0 ? title : `Terminal ${index + 1}`;
}

export function resize(session: TerminalSession, cols: number, rows: number) {
  if (cols === session.cols && rows === session.rows) return session;
  return { ...session, cols, rows };
}
